#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct PatchIn {
    op: String,
    repo_id: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    key: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    epoch: Option<u32>,
    #[serde(default, skip_serializing_if = "Option::is_none", rename = "type")]
    kind: Option<DocKind>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    owner_id: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    props: Option<BTreeMap<String, Value>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    base_public: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    source_public: Option<bool>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    head: Option<HeadIn>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    nonce: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    context: Option<OpenCtxIn>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    doc: Option<StoredDocIn>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    plain_head: Option<String>,
}

#[derive(Deserialize, Serialize)]
#[serde(rename_all = "camelCase", deny_unknown_fields)]
struct HeadIn {
    real: String,
    salt: String,
}

fn run_sealed_patch(v: &Vector) -> Value {
    let i: PatchIn = input(v);
    let repo_id = h32(&i.repo_id);
    match i.op.as_str() {
        "seal" => {
            let keys =
                EpochKeys::derive(&repo_id, i.epoch.unwrap(), &key(i.key.as_deref().unwrap()));
            let props = i
                .props
                .unwrap()
                .into_iter()
                .map(|(k, val)| {
                    let f = collab_field(&k, &val);
                    (k, f)
                })
                .collect();
            let patch = MembersPatch {
                base_public: i.base_public.unwrap(),
                source_public: i.source_public.unwrap(),
                head: i.head.map(|h| HeadBlind {
                    real: bytes(&h.real),
                    salt: salt_of(&h.salt),
                }),
            };
            match crate::collab::private::seal_members_props_with_nonce(
                &keys,
                i.kind.unwrap(),
                h32(i.owner_id.as_deref().unwrap()),
                props,
                &patch,
                nonce12(i.nonce.as_deref().unwrap()),
            ) {
                Ok(sealed) => json!({
                    "props": sealed
                        .iter()
                        .map(|(k, val)| (k.clone(), collab_json(val)))
                        .collect::<serde_json::Map<_, _>>(),
                }),
                Err(e) if e.to_string().contains("malformed") => json!({ "error": "malformed" }),
                Err(e) => panic!("vector `{}`: {e}", v.name),
            }
        }
        "open" => {
            let ctx = open_context(&repo_id, i.context.as_ref().unwrap());
            let (header, enc) = i.doc.as_ref().unwrap().split();
            let Opened::Readable(mut fields) = doc::open_content(&ctx, &header, &enc) else {
                return opened_json(&doc::open_content(&ctx, &header, &enc));
            };
            let plain = bytes(i.plain_head.as_deref().unwrap());
            let Some(head) =
                blind::head_of(&plain, fields.head_oid.as_deref(), fields.oid_salt.as_ref())
            else {
                return json!({ "status": "malformed" });
            };
            fields.head_oid = None;
            fields.oid_salt = None;
            let mut out = json!({ "status": "readable", "fields": fields, "alerts": [] });
            match head {
                Head::Plain => {}
                Head::Real { real, salt } => {
                    out["head"] = json!({ "real": hex::encode(real), "salt": hex::encode(salt) });
                }
                Head::Alert(a) => out["alerts"] = json!([alert_json(a)]),
            }
            out
        }
        other => panic!("vector `{}`: sealed_patch op `{other}`", v.name),
    }
}

