/// An object graph held in memory.
struct MemGraph<'a>(&'a GuardIn);

impl MemGraph<'_> {
    fn reach(&self, tips: &[String], objects: bool) -> BTreeSet<String> {
        let mut seen = BTreeSet::new();
        let mut stack: Vec<String> = tips.to_vec();
        while let Some(x) = stack.pop() {
            if seen.contains(&x) {
                continue;
            }
            let o = &self.0.objects[&x];
            match o.kind {
                ObjectType::Commit => {
                    seen.insert(x);
                    stack.extend(o.parents.iter().flatten().cloned());
                    if objects {
                        stack.extend(o.tree.clone());
                    }
                }
                ObjectType::Tag => {
                    if objects {
                        seen.insert(x);
                    }
                    stack.push(o.target.clone().unwrap());
                }
                ObjectType::Tree if objects => {
                    seen.insert(x);
                    stack.extend(o.entries.iter().flatten().cloned());
                }
                ObjectType::Blob if objects => {
                    seen.insert(x);
                }
                ObjectType::Tree | ObjectType::Blob => {}
            }
        }
        seen
    }
}

impl ObjectGraph for MemGraph<'_> {
    fn commits(
        &self,
        include: &[String],
        exclude: &[String],
    ) -> crate::error::Result<BTreeSet<String>> {
        let ex = self.reach(exclude, false);
        Ok(self
            .reach(include, false)
            .difference(&ex)
            .cloned()
            .collect())
    }
    fn objects(
        &self,
        include: &[String],
        exclude: &[String],
    ) -> crate::error::Result<BTreeSet<String>> {
        let ex = self.reach(exclude, true);
        Ok(self.reach(include, true).difference(&ex).cloned().collect())
    }
    fn peel(&self, oid: &str) -> crate::error::Result<Peeled> {
        let mut tags = Vec::new();
        let mut x = oid.to_owned();
        while self.0.objects[&x].kind == ObjectType::Tag {
            tags.push(x.clone());
            x = self.0.objects[&x].target.clone().unwrap();
        }
        let kind = self.0.objects[&x].kind;
        Ok(Peeled {
            tags,
            target: x,
            kind,
        })
    }
    fn note_targets(&self, oid: &str) -> crate::error::Result<Vec<String>> {
        Ok(self.0.notes.get(oid).cloned().unwrap_or_default())
    }
}

fn run_guard(v: &Vector) -> Value {
    let i: GuardIn = input(v);
    let state = match &i.ledger {
        None => ledger::State::Absent,
        Some(LedgerIn::Unknown(s)) if s == "unknown" => ledger::State::Unknown,
        Some(LedgerIn::Unknown(s)) => panic!("ledger `{s}`"),
        Some(LedgerIn::Entries(es)) => {
            let mut l = ledger::Ledger::default();
            for e in es {
                let a = e
                    .audience
                    .as_deref()
                    .map_or(EntryAudience::Members, |t| EntryAudience::parse(t).unwrap());
                let a = match l.commits.remove(&e.oid) {
                    Some(prev) => prev.narrowest(a),
                    None => a,
                };
                l.commits.insert(e.oid.clone(), a);
            }
            ledger::State::Present(l)
        }
    };
    let out = guard::guard(
        &MemGraph(&i),
        &guard::GuardInput {
            members_key: i.members_key,
            ledger: &state,
            decryptable: i.decryptable.as_deref(),
            public_tips: &i.public_tips,
            batch: &i.batch,
            publish_private: i.publish_private.as_deref(),
        },
    )
    .unwrap();
    serde_json::to_value(out).unwrap()
}

fn run(v: &Vector) -> Value {
    match v.case.as_str() {
        "oid_blind" => run_oid_blind(v),
        "sealed_ref" => run_sealed_ref(v),
        "sealed_patch" => run_sealed_patch(v),
        "members_pack_plan" => {
            let i: PlanIn = input(v);
            serde_json::to_value(plan::plan(&i.public_tips, &i.members_tips, &i.batch)).unwrap()
        }
        "publish_guard" => run_guard(v),
        other => panic!("vector `{}`: not a members-git case `{other}`", v.name),
    }
}

#[test]
fn members_git_conformance_vectors() {
    let dir = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../forge-contracts/vectors");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .expect("read vectors dir")
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| CASES.iter().any(|c| n.starts_with(&format!("{c}__"))))
        })
        .collect();
    files.sort();
    let mut ran = BTreeMap::<String, usize>::new();
    for path in &files {
        let v: Vector = serde_json::from_slice(&std::fs::read(path).unwrap())
            .unwrap_or_else(|e| panic!("parse {}: {e}", path.display()));
        assert_eq!(v.rules, "v2", "{}", path.display());
        assert_eq!(run(&v), v.expected, "vector `{}` ({})", v.name, v.case);
        *ran.entry(v.case.clone()).or_default() += 1;
    }
    for c in CASES {
        assert!(ran.get(c).copied().unwrap_or(0) >= 5, "ran {ran:?}");
    }
    assert!(ran.values().sum::<usize>() >= 98, "ran {ran:?}");
}
